import { CommonModule } from '@angular/common';
import { Component, DestroyRef, HostBinding, effect, inject, input, output, signal, } from '@angular/core';
import { MessageVariant } from './ap-message.interface';
import { ApIconComponent } from '../ap-icon/ap-icon.component';

@Component({
  selector: 'ap-message',
  imports: [CommonModule, ApIconComponent],
  templateUrl: './ap-message.component.html',
  styleUrl: './ap-message.component.css',
})
export class ApMessageComponent {
  private static readonly COUNTDOWN_MS = 3000;
  private static readonly EXIT_MS = 250;
  private readonly destroyRef = inject(DestroyRef);
  private countdownTimeoutId: ReturnType<typeof setTimeout> | null = null;
  private exitTimeoutId: ReturnType<typeof setTimeout> | null = null;
  readonly message = input<string>('');
  readonly variant = input<MessageVariant>('secondary');
  readonly autoDismiss = input<boolean>(true);
  readonly closed = output<void>();
  readonly isRendered = signal(true);
  readonly isClosing = signal(false);

  @HostBinding('class')
  get hostClasses(): string {
    return 'block w-full';
  }

  constructor() {
    effect(() => {
      this.message();
      this.restartTimer();
    });

    this.destroyRef.onDestroy(() => {
      this.clearTimers();
    });
  }

  get containerClasses(): string {
    const base = 'w-full px-4 py-3 font-medium leading-6';
    const variants: Record<MessageVariant, string> = {
      success: 'bg-green-950/80 text-green-500',
      info: 'bg-blue-950/80 text-blue-500',
      warn: ' bg-yellow-950/40 text-amber-400',
      error: ' bg-red-950/50 text-red-500',
      secondary: ' bg-zinc-800 text-zinc-100',
      contrast: ' bg-zinc-50 text-zinc-950',
      origin: ' bg-slate-950/50 text-slate-300',
    };
    return `${base} ${variants[this.variant()]}`;
  }

  dismiss(): void {
    if (this.isClosing() || !this.isRendered()) {
      return;
    }

    this.clearTimers();
    this.isClosing.set(true);
    this.exitTimeoutId = setTimeout(() => {
      this.isRendered.set(false);
      this.closed.emit();
    }, ApMessageComponent.EXIT_MS);
  }

  private restartTimer(): void {
    this.clearTimers();
    this.isRendered.set(true);
    this.isClosing.set(false);

    if (!this.autoDismiss()) {
      return;
    }

    this.countdownTimeoutId = setTimeout(() => {
      this.dismiss();
    }, ApMessageComponent.COUNTDOWN_MS);
  }

  private clearTimers(): void {
    if (this.countdownTimeoutId !== null) {
      clearTimeout(this.countdownTimeoutId);
      this.countdownTimeoutId = null;
    }

    if (this.exitTimeoutId !== null) {
      clearTimeout(this.exitTimeoutId);
      this.exitTimeoutId = null;
    }
  }
}
